        {canManageFolders && addingToParentIdExt === folder.id && (
           <form onSubmit={handleAddNewFolderExt} className="my-1" style={{ paddingLeft: `${(level + 1) * 1.5}rem` }}>
               <input
                 type="text"
                 autoFocus
